function hanoi(n: number, from: string, to: string, via: string): number {
	if (n === 0) return 0;
	const before = hanoi(n - 1, from, via, to); // free the largest disc
	const after = hanoi(n - 1, via, to, from);  // put the others back on top
	return before + 1 + after;                  // T(n) = 2 T(n - 1) + 1
}

